"use strict";
/* z3: UX polish + Zoom labels + UTM tracking installer (supersedes z2 —
 * contains everything). Replaces the listed files (backups .bak3),
 * syntax-checks, restarts, prints health. Run: node z3.js */
const fs = require("fs"), path = require("path"), cp = require("child_process");
const APP = process.argv[2] || "/opt/foglalas-engine";
const FILES = {"src/bookingpages.js": "", "src/booking.js": "", "src/emailhtml.js": "", "src/templates.js": "", "src/engine.js": ""};
try {
  for (const [rel, b64] of Object.entries(FILES)) {
    const p = path.join(APP, rel);
    if (!fs.existsSync(p)) { console.error("MISSING " + p); process.exit(1); }
    fs.copyFileSync(p, p + ".bak3");
    fs.writeFileSync(p, Buffer.from(b64, "base64"));
    cp.execSync("node --check " + p);
    console.log("updated " + rel);
  }
  console.log("syntax ok");
  if (process.argv[3] !== "norestart") {
    cp.execSync("systemctl restart foglalas-engine");
    cp.execSync("sleep 3");
    const out = cp.execSync("curl -s http://localhost:3000/health").toString();
    console.log("health: " + out);
    console.log(out.includes('"ok":true') ? "Z3-DEPLOY-DONE" : "HEALTH-NOT-OK check journalctl -u foglalas-engine");
  } else console.log("norestart done");
} catch (e) { console.error("FAILED: " + e.message); process.exit(1); }
